-- Step 2 / 0004: encrypted message relay queue
-- The server stores ONLY ciphertext. The recipient deletes the row after receiving it (ACK).
-- Anything older than 30 days is purged by pg_cron (0006).

create table public.pending_messages (
  id uuid primary key default gen_random_uuid(),
  sender_id uuid not null references public.users (id) on delete cascade,
  recipient_id uuid not null references public.users (id) on delete cascade,
  -- Generated by the sender; makes retries idempotent (duplicate = already sent)
  client_message_id uuid not null,
  -- libsignal ciphertext type (prekey message, normal message, ...)
  message_type smallint not null check (message_type between 0 and 255),
  ciphertext bytea not null check (octet_length(ciphertext) between 1 and 65536),
  created_at timestamptz not null default now(),
  unique (sender_id, client_message_id)
);

create index pending_messages_recipient_idx
  on public.pending_messages (recipient_id, created_at);

alter table public.pending_messages enable row level security;

create policy pm_insert_as_sender on public.pending_messages
  for insert to authenticated
  with check (sender_id = (select auth.uid()) and sender_id <> recipient_id);

-- Only the recipient can read (and Realtime delivers only to them)
create policy pm_select_recipient on public.pending_messages
  for select to authenticated
  using (recipient_id = (select auth.uid()));

-- ACK = recipient deletes the row
create policy pm_delete_recipient on public.pending_messages
  for delete to authenticated
  using (recipient_id = (select auth.uid()));

-- If the recipient blocked the sender, the insert is silently dropped (sender cannot tell).
-- Also caps how many undelivered messages one mailbox can hold.
create function public.pending_messages_before_insert() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if public.is_blocked(new.sender_id, new.recipient_id) then
    return null;
  end if;
  if (select count(*) from public.pending_messages m
      where m.recipient_id = new.recipient_id) >= 5000 then
    raise exception 'mailbox_full';
  end if;
  return new;
end $$;

create trigger pending_messages_guard
  before insert on public.pending_messages
  for each row execute function public.pending_messages_before_insert();

-- Realtime: new rows are pushed to the recipient (respects RLS)
alter publication supabase_realtime add table public.pending_messages;
